diff --git a/src/platform/text_input_host.c b/src/platform/text_input_host.c
new file mode 100644
index 0000000..5f92304
--- /dev/null
+++ b/src/platform/text_input_host.c
@@ -0,0 +1,123 @@
+#include <stdlib.h>
+#include <string.h>
+#include <raylib.h>
+#include "text_input.h"
+
+// Room for VD_TEXT_INPUT_MAX_LENGTH code units: at most 3 UTF-8 bytes per unit, plus the terminator.
+static char text[VD_TEXT_INPUT_MAX_LENGTH * 3 + 1];
+static size_t text_bytes = 0;
+static int text_units = 0;
+static int max_units = 0;
+static bool editing = false;
+
+static int utf16_units(int codepoint)
+{
+    return codepoint >= 0x10000 ? 2 : 1;
+}
+
+static bool append_codepoint(int codepoint)
+{
+    if (codepoint < 0x20 || codepoint == 0x7f || codepoint > 0x10ffff) return false;
+    if (codepoint >= 0xd800 && codepoint <= 0xdfff) return false;
+    if (text_units + utf16_units(codepoint) > max_units) return false;
+
+    int size = 0;
+    const char *utf8 = CodepointToUTF8(codepoint, &size);
+    memcpy(text + text_bytes, utf8, (size_t)size);
+    text_bytes += (size_t)size;
+    text[text_bytes] = '\0';
+    text_units += utf16_units(codepoint);
+    return true;
+}
+
+static void delete_last_codepoint(void)
+{
+    if (text_bytes == 0) return;
+    size_t start = text_bytes - 1;
+    while (start > 0 && ((unsigned char)text[start] & 0xc0) == 0x80)
+        start--;
+    int size = 0;
+    text_units -= utf16_units(GetCodepointNext(text + start, &size));
+    text_bytes = start;
+    text[text_bytes] = '\0';
+}
+
+// Escape quits a raylib app by default; while editing it cancels instead.
+static void set_editing(bool value)
+{
+    editing = value;
+    SetExitKey(value ? KEY_NULL : KEY_ESCAPE);
+}
+
+bool vd_text_input_begin(const char *title, const char *initial, int max_length)
+{
+    (void)title;
+    if (editing) return false;
+
+    max_units = max_length < 1 ? 1 : max_length > VD_TEXT_INPUT_MAX_LENGTH ? VD_TEXT_INPUT_MAX_LENGTH : max_length;
+    text_bytes = 0;
+    text_units = 0;
+    text[0] = '\0';
+    for (const char *p = initial ? initial : ""; *p != '\0';) {
+        int size = 0;
+        int codepoint = GetCodepointNext(p, &size);
+        p += size;
+        if (text_units + utf16_units(codepoint) > max_units) break;
+        append_codepoint(codepoint);
+    }
+
+    set_editing(true);
+    return true;
+}
+
+VdTextInputStatus vd_text_input_apply_keys(const VdTextInputKeys *keys)
+{
+    if (!editing) return VD_TEXT_INPUT_IDLE;
+
+    if (keys->cancel) {
+        set_editing(false);
+        return VD_TEXT_INPUT_CANCELLED;
+    }
+    for (int i = 0; i < keys->codepoint_count; i++)
+        append_codepoint(keys->codepoints[i]);
+    if (keys->backspace) delete_last_codepoint();
+    if (keys->confirm) {
+        set_editing(false);
+        return VD_TEXT_INPUT_CONFIRMED;
+    }
+    return VD_TEXT_INPUT_EDITING;
+}
+
+VdTextInputStatus vd_text_input_poll(void)
+{
+    if (!editing) return VD_TEXT_INPUT_IDLE;
+
+    int codepoints[32];
+    int count = 0;
+    for (int codepoint = GetCharPressed(); codepoint != 0 && count < 32; codepoint = GetCharPressed())
+        codepoints[count++] = codepoint;
+
+    const VdTextInputKeys keys = {
+        .codepoints = codepoints,
+        .codepoint_count = count,
+        .backspace = IsKeyPressed(KEY_BACKSPACE) || IsKeyPressedRepeat(KEY_BACKSPACE),
+        .confirm = IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_KP_ENTER),
+        .cancel = IsKeyPressed(KEY_ESCAPE),
+    };
+    return vd_text_input_apply_keys(&keys);
+}
+
+const char *vd_text_input_text(void)
+{
+    return text;
+}
+
+void vd_text_input_cancel(void)
+{
+    if (editing) set_editing(false);
+}
+
+bool vd_text_input_edits_in_place(void)
+{
+    return true;
+}

diff --git a/src/platform/text_input_vita.c b/src/platform/text_input_vita.c
new file mode 100644
index 0000000..cb4f8cb
--- /dev/null
+++ b/src/platform/text_input_vita.c
@@ -0,0 +1,130 @@
+#include <string.h>
+#include <psp2/kernel/clib.h>
+#include <psp2/common_dialog.h>
+#include <psp2/ime_dialog.h>
+#include <psp2/sysmodule.h>
+#include <raylib.h>
+#include "text_input.h"
+
+// raylib-vita's SDL swap calls vglSwapBuffers(GL_TRUE), so EndDrawing already updates the common dialog each frame.
+typedef enum { IME_IDLE, IME_RUNNING, IME_ABORTING } ImeState;
+
+static ImeState state = IME_IDLE;
+static SceWChar16 title16[SCE_IME_DIALOG_MAX_TITLE_LENGTH];
+static SceWChar16 initial16[VD_TEXT_INPUT_MAX_LENGTH + 1];
+static SceWChar16 input16[VD_TEXT_INPUT_MAX_LENGTH + 1];
+static char result[VD_TEXT_INPUT_MAX_LENGTH * 3 + 1];
+
+// Writes at most capacity - 1 code units and a terminator, never splitting a surrogate pair.
+static void utf8_to_utf16(const char *src, SceWChar16 *out, int capacity)
+{
+    int n = 0;
+    while (*src != '\0') {
+        int size = 0;
+        int codepoint = GetCodepointNext(src, &size);
+        src += size;
+        if (codepoint >= 0x10000) {
+            if (n + 2 >= capacity) break;
+            codepoint -= 0x10000;
+            out[n++] = (SceWChar16)(0xd800 + (codepoint >> 10));
+            out[n++] = (SceWChar16)(0xdc00 + (codepoint & 0x3ff));
+        } else {
+            if (n + 1 >= capacity) break;
+            out[n++] = (SceWChar16)codepoint;
+        }
+    }
+    out[n] = 0;
+}
+
+// Unpaired surrogates are dropped.
+static void utf16_to_utf8(const SceWChar16 *src, char *out, size_t capacity)
+{
+    size_t n = 0;
+    for (; *src != 0; src++) {
+        int codepoint = *src;
+        if (codepoint >= 0xd800 && codepoint <= 0xdbff && src[1] >= 0xdc00 && src[1] <= 0xdfff) {
+            codepoint = 0x10000 + ((codepoint - 0xd800) << 10) + (src[1] - 0xdc00);
+            src++;
+        } else if (codepoint >= 0xd800 && codepoint <= 0xdfff) {
+            continue;
+        }
+        int size = 0;
+        const char *utf8 = CodepointToUTF8(codepoint, &size);
+        if (n + (size_t)size >= capacity) break;
+        memcpy(out + n, utf8, (size_t)size);
+        n += (size_t)size;
+    }
+    out[n] = '\0';
+}
+
+bool vd_text_input_begin(const char *title, const char *initial, int max_length)
+{
+    static bool ime_module_loaded = false;
+    if (state != IME_IDLE) return false;
+    if (!ime_module_loaded) {
+        sceSysmoduleLoadModule(SCE_SYSMODULE_IME);
+        ime_module_loaded = true;
+    }
+
+    int max_units = max_length < 1 ? 1 : max_length > VD_TEXT_INPUT_MAX_LENGTH ? VD_TEXT_INPUT_MAX_LENGTH : max_length;
+    utf8_to_utf16(title ? title : "", title16, SCE_IME_DIALOG_MAX_TITLE_LENGTH);
+    utf8_to_utf16(initial ? initial : "", initial16, max_units + 1);
+    memset(input16, 0, sizeof(input16));
+
+    SceImeDialogParam param;
+    sceImeDialogParamInit(&param);
+    param.supportedLanguages = SCE_IME_LANGUAGE_ENGLISH;
+    param.languagesForced = SCE_FALSE;
+    param.type = SCE_IME_TYPE_DEFAULT;
+    param.dialogMode = SCE_IME_DIALOG_DIALOG_MODE_WITH_CANCEL;
+    param.textBoxMode = SCE_IME_DIALOG_TEXTBOX_MODE_WITH_CLEAR;
+    param.title = title16;
+    param.maxTextLength = (SceUInt32)max_units;
+    param.initialText = initial16;
+    param.inputTextBuffer = input16;
+    if (sceImeDialogInit(&param) < 0) {
+        TraceLog(LOG_WARNING, "IME dialog did not start");
+        return false;
+    }
+    state = IME_RUNNING;
+    return true;
+}
+
+VdTextInputStatus vd_text_input_poll(void)
+{
+    if (state == IME_IDLE) return VD_TEXT_INPUT_IDLE;
+    if (sceImeDialogGetStatus() != SCE_COMMON_DIALOG_STATUS_FINISHED) {
+        return state == IME_RUNNING ? VD_TEXT_INPUT_EDITING : VD_TEXT_INPUT_IDLE;
+    }
+
+    VdTextInputStatus status = VD_TEXT_INPUT_CANCELLED;
+    if (state == IME_RUNNING) {
+        SceImeDialogResult dialog_result;
+        memset(&dialog_result, 0, sizeof(dialog_result));
+        sceImeDialogGetResult(&dialog_result);
+        if (dialog_result.button == SCE_IME_DIALOG_BUTTON_ENTER) {
+            utf16_to_utf8(input16, result, sizeof(result));
+            status = VD_TEXT_INPUT_CONFIRMED;
+        }
+    }
+    sceImeDialogTerm();
+    state = IME_IDLE;
+    return status;
+}
+
+const char *vd_text_input_text(void)
+{
+    return result;
+}
+
+void vd_text_input_cancel(void)
+{
+    if (state != IME_RUNNING) return;
+    sceImeDialogAbort();
+    state = IME_ABORTING;
+}
+
+bool vd_text_input_edits_in_place(void)
+{
+    return false;
+}
